import ipaddress as ip

rules = [  # (번호, 이름, 출발지, 목적지, 포트, 동작)
    (1, "allow-web",   "10.0.0.0/8",  "172.16.0.0/16",  {443},  "allow"),
    (2, "deny-db",     "10.0.0.0/8",  "172.16.5.0/24",  {5432}, "deny"),
    (3, "allow-https", "10.1.0.0/16", "172.16.5.0/24",  {443},  "allow"),
    (4, "allow-pg",    "10.1.2.0/24", "172.16.5.10/32", {5432}, "allow"),
]

def covers(a, b):
    return (ip.ip_network(a[2]).supernet_of(ip.ip_network(b[2]))
            and ip.ip_network(a[3]).supernet_of(ip.ip_network(b[3]))
            and b[4] <= a[4])

for i, r in enumerate(rules):
    for up in rules[:i]:
        if covers(up, r):
            kind = "중복(지워도 됨)" if up[5] == r[5] else "가려짐(절대 안 맞음)"
            print(f"규칙 {r[0]} {r[1]} → 규칙 {up[0]} {up[1]} 에 {kind}")
            break

# 규칙 3 allow-https → 규칙 1 allow-web 에 중복(지워도 됨)
# 규칙 4 allow-pg → 규칙 2 deny-db 에 가려짐(절대 안 맞음)
